-- Prestigious Cache rewards.
--
-- Built exactly like the Callboard Caches: the named Prestigious Cache pays the normal row of its
-- own content and nothing else, so a Zul'Gurub Cache never pays a Naxxramas item and no cache ever
-- pays a Heroic, Mythic or Ascended copy of the gear it names. Items Ascension retired ('This Token
-- has been deprecated ...') are in no pool, including the class tier tokens the raids still delete
-- gate behind, which is why a Karazhan Cache never pays a 'Fallen Hero' token any more.
--
-- The tier tokens such a cache also rolls by chance are not here either: a token belongs to the
-- content its reward comes from, so it lives in `ascension_cache_content_token` next to that cache.
--
-- StatType is the item's dominant stat, 1 Strength, 2 Agility, 3 Intellect, 4 Spirit, 5 Misc, which
-- is the "Gear selectable from your stat type" the cache's own description promises.

DROP TABLE IF EXISTS `ascension_prestigious_cache_reward`;
CREATE TABLE `ascension_prestigious_cache_reward` (
  `CacheItemId` INT UNSIGNED NOT NULL,
  `RewardItemId` INT UNSIGNED NOT NULL,
  `RewardItemLevel` SMALLINT UNSIGNED NOT NULL,
  `StatType` TINYINT UNSIGNED NOT NULL DEFAULT 5,
  `ArmorClass` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`CacheItemId`, `RewardItemId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `ascension_prestigious_cache_reward`;
